WITH filtered_orders AS (SELECT * FROM orders WHERE order_date >= '2023-03-01' AND (discount >= 0.16 OR customer_id IS NULL)), agg AS (SELECT CASE WHEN amount >= 1660 THEN 'high' WHEN amount >= 320 THEN 'mid' ELSE 'low' END AS amount_bucket, status, AVG(shipping_fee) AS avg_shipping_fee, SUM(shipping_fee) AS total_shipping_fee FROM filtered_orders GROUP BY CASE WHEN amount >= 1660 THEN 'high' WHEN amount >= 320 THEN 'mid' ELSE 'low' END, status) SELECT amount_bucket, status, avg_shipping_fee, total_shipping_fee FROM agg ORDER BY amount_bucket ASC, status ASC LIMIT 5
